import java.util.HashMap; 
import java.util.Map; 

public class TwoSum { 
    public int[] twoSum(int[] nums, int target) { 
        Map<Integer, Integer> seen = new HashMap<>(); 
        for (int i = 0; i < nums.length; i++) { 
            int complement = target - nums[i]; 
            if (seen.containsKey(complement)) { 
                return new int[] { seen.get(complement), i }; 
            } 
            seen.put(nums[i], i); 
        } 
        throw new IllegalArgumentException("No solution found"); 
    } 

    public static void main(String[] args) { 
        TwoSum solver = new TwoSum(); 
        int[] result = solver.twoSum(new int[] {2, 7, 11, 15}, 9); 
        System.out.println(result[0] + ", " + result[1]); 
    } 
}

class Solution {
    public TreeNode insertIntoBST(TreeNode root, int val) {
        if(root==null){
            return new TreeNode(val);
        }
        if(root.val<val){
            root.right=insertIntoBST(root.right,val);
        }
        else{
            root.left=insertIntoBST(root.left,val);
        }
        return root;
    }
}

class Solution {
    public boolean areAnagrams(Node root1, Node root2) {
        Queue<Node> q1=new LinkedList<>();
        Queue<Node> q2=new LinkedList<>();
        q1.offer(root1);
        q2.offer(root2);
        while(!q1.isEmpty() || !q2.isEmpty()){
           int s1=q1.size();
           int s2=q2.size();
           if(s1!=s2){
               return false;
           }
           Map<Integer,Integer> map=new HashMap<>();
           for(int i=0;i<s1;i++){
               Node curr=q1.poll();
               map.put(curr.data,map.getOrDefault(curr.data,0)+1);
               if(curr.left!=null){
                   q1.offer(curr.left);
               }
               if(curr.right!=null){
                   q1.offer(curr.right);
               }
           }
           for(int i=0;i<s2;i++){
               Node curr=q2.poll();
               if(!map.containsKey(curr.data)){
                   return false;
               }
               map.put(curr.data,map.get(curr.data)-1);
               if(map.get(curr.data)==0){
                   map.remove(curr.data);
               }
               if(curr.left!=null){
                   q2.offer(curr.left);
               }
               if(curr.right!=null){
                   q2.offer(curr.right);
               }

           }
           if(!map.isEmpty()) {
               return false;
           }
        }

        return q1.isEmpty() && q2.isEmpty();

    }
}

class Solution {
    public List<Integer> reverseLevelOrder(Node root) {
        LinkedList<Node> ll=new LinkedList<>();
        LinkedList<Integer> result=new LinkedList<>();
        if(root==null){
            return result;
        }
        ll.addFirst(root);
        while(!ll.isEmpty()){
            int size=ll.size();
            for(int i=0;i<size;i++){
                Node node=ll.pollFirst();
                result.addFirst(node.data);
                if(node.right!=null){
                    ll.addLast(node.right);
                }
                if(node.left!=null){
                    ll.addLast(node.left);
                }
            }
        }
        return result;
    }
}
